package net.minecraft.network.chat;public class MutableComponent implements Component {private String text;public MutableComponent(String t){text=t;}public String getString(){return text;}public MutableComponent copy(){return new MutableComponent(text);}public MutableComponent append(Component c){text+=c.getString();return this;}public MutableComponent append(String s){text+=s;return this;}public MutableComponent withStyle(net.minecraft.ChatFormatting... c){return this;}}